<?php
if(!defined('ABSPATH'))exit;
add_action('init',function(){if(get_option('bhc_catalog_image_sony_tv_s30_v267'))return;$items=[['sku'=>'BHC-SONY-K-55S30','src'=>__DIR__.'/sony-k55s30-source.png','rel'=>'bhc-image-references/sony-k55s30.png','label'=>'Sony K-55S30'],['sku'=>'BHC-SONY-K-75S30','src'=>__DIR__.'/sony-k75s30-source.png','rel'=>'bhc-image-references/sony-k75s30.png','label'=>'Sony K-75S30']];$out=[];foreach($items as $it){$id=wc_get_product_id_by_sku($it['sku']);$file=ABSPATH.'wp-content/uploads/'.$it['rel'];$ok=false;$aid=0;if($id&&is_readable($it['src'])){$im=@imagecreatefrompng($it['src']);if($im){wp_mkdir_p(dirname($file));$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=max(1,(int)round($w*$scale));$nh=max(1,(int)round($h*$scale));$c=imagecreatetruecolor($nw,$nh);imagealphablending($c,false);imagesavealpha($c,true);$z=imagecolorallocatealpha($c,0,0,0,127);imagefill($c,0,0,$z);imagecopyresampled($c,$im,0,0,0,0,$nw,$nh,$w,$h);imagepng($c,$file,6);imagedestroy($c);imagedestroy($im);$ok=is_readable($file);}}if($ok){$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>$it['label'].' اختصاصی 4K شفاف - نیازمند تطبیق نهایی','post_status'=>'inherit','post_parent'=>$id],$file,$id);if($aid&&!is_wp_error($aid)){update_post_meta($aid,'_wp_attached_file',$it['rel']);$q=@getimagesize($file);wp_update_attachment_metadata($aid,['width'=>$q[0]??4096,'height'=>$q[1]??4096,'file'=>$it['rel'],'sizes'=>[]]);set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','product_specific_generated_candidate');update_post_meta($id,'_bhc_image_status','generated_4k_transparent_candidate');update_post_meta($id,'_bhc_image_long_edge',max((int)($q[0]??0),(int)($q[1]??0)));update_post_meta($id,'_bhc_image_featured_verified','yes');}}$out[$it['label']]=['id'=>$id,'ok'=>$ok,'attachment'=>$aid];}update_option('bhc_catalog_image_sony_tv_s30_v267',['items'=>$out,'at'=>current_time('mysql')],false);},267);
